import sys
input = sys.stdin.read

def is_prime(n):
    if n < 2:
        return False
    if n in (2, 3):
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def smallest_starting_number(x2):
    x0 = x2 - 1
    while x0 >= 3:
        for p1 in range(2, x0):
            if is_prime(p1):
                x1 = ((x0 - 1) + p1) // p1 * p1
                if x1 >= x0:
                    for p2 in range(2, x1):
                        if is_prime(p2):
                            x2_test = ((x1 - 1) + p2) // p2 * p2
                            if x2_test == x2:
                                return x0
        x0 -= 1
    return x0

